import {CommandRegistry} from '../../../foundation/models.js';
import {RQDomainAdapter} from '../../../adapters/rq/domain.js';
import {bindRqSurface} from '../../../surfaces/rq/surface.js';
import {VisualizeDomainAdapter} from '../../../adapters/visualize/domain.js';
import {bindVisualizeSurface} from '../../../surfaces/visualize/surface.js';

const clone=value=>structuredClone(value),json=value=>JSON.stringify(value);
const assert=(condition,message='assertion failed')=>{if(!condition)throw Error(message);};
const ref=(revision,digest)=>({sourceId:'SRC-001',revision,digest,locator:`rq://sources/SRC-001/${revision}`});
const rqRecords=()=>[
  {sourceId:'SRC-001',revision:'r1',digest:'sha-r1',locator:'rq://sources/SRC-001/r1',schemaVersion:'rq-source/1',comparable:{title:{label:'Title',type:'text',value:'Before'},confidence:{label:'Confidence',type:'number',value:0.6}}},
  {sourceId:'SRC-001',revision:'r2',digest:'sha-r2',locator:'rq://sources/SRC-001/r2',schemaVersion:'rq-source/1',comparable:{title:{label:'Title',type:'text',value:'After'},confidence:{label:'Confidence',type:'number',value:0.8}}},
  {sourceId:'SRC-X',revision:'r1',digest:'sha-x',locator:'rq://sources/SRC-X/r1',schemaVersion:'rq-source/1',status:'EXCLUDED',excluded:true,comparable:{title:{label:'Title',type:'text',value:'Excluded'}}}
];
const reps=()=>[
  {representationId:'rep-a',canonicalRef:{objectId:'obj-a',revision:'r1'},label:'Object A',x:20,y:40,views:['TREE','PATH','GRAPH','CANVAS']},
  {representationId:'rep-b',canonicalRef:{objectId:'obj-b',revision:'r1'},label:'Object B',x:180,y:80,views:['TREE','PATH','GRAPH','CANVAS']}
];
function sharedSpatial(registry){for(const id of ['spatial.connect','spatial.relation.commit','relation.edit','relation.undo','relation.redo','spatial.fit','spatial.align','spatial.distribute'])registry.register(id,id.startsWith('relation')||id.includes('relation')?'RelationDomainAdapter':'SpatialInteractionKernel',id,()=>({ok:true}));}

export function runS09ReexecutionTests(){
  const tests=[],test=(id,fn)=>{try{tests.push({id,status:'PASS',detail:fn()??'PASS'});}catch(error){tests.push({id,status:'FAIL',detail:String(error?.stack||error)});}};
  test('rq.compare-negative-missing-exact-pair-context',()=>{const a=new RQDomainAdapter(rqRecords()),r=new CommandRegistry();bindRqSurface({commands:r,adapter:a});const before=json(a.records),av=r.availability('rq.compare',{left:ref('r1','sha-r1'),right:null,workingAnalysisId:'A',scope:['claims']}),res=r.execute('rq.compare',{left:ref('r1','sha-r1'),workingAnalysisId:'A',scope:['claims']});assert(!av.enabled&&av.code==='RQ_COMPARE_EXACT_SOURCE_REVISION_PAIR_REQUIRED'&&res.ok===false&&a.sessions.size===0&&before===json(a.records));});
  test('rq.compare-positive-exact-pair-and-context',()=>{const a=new RQDomainAdapter(rqRecords()),r=new CommandRegistry();bindRqSurface({commands:r,adapter:a});const payload={left:ref('r1','sha-r1'),right:ref('r2','sha-r2'),workingAnalysisId:'analysis-1',scope:['claims','provenance']},av=r.availability('rq.compare',payload),res=r.execute('rq.compare',payload);assert(av.enabled&&res.ok&&a.sessions.has('analysis-1')&&res.context.scope.join()==='claims,provenance'&&res.formalReview===false);return res.status;});
  test('rq.compare-swap-reverses-pair-without-source-rewrite',()=>{const records=rqRecords(),before=json(records),a=new RQDomainAdapter(records),one=a.compare({left:ref('r1','sha-r1'),right:ref('r2','sha-r2'),workingAnalysisId:'one',scope:['claims']}),two=a.compare({left:ref('r2','sha-r2'),right:ref('r1','sha-r1'),workingAnalysisId:'two',scope:['claims']});assert(one.ok&&two.ok&&one.pair.left.ref.revision==='r1'&&two.pair.left.ref.revision==='r2'&&one.pair.right.ref.revision==='r2'&&two.pair.right.ref.revision==='r1'&&before===json(records));});
  test('rq.review-working-conflict-never-w04-decision',()=>{const a=new RQDomainAdapter(rqRecords());a.compare({left:ref('r1','sha-r1'),right:ref('r2','sha-r2'),workingAnalysisId:'review-1',scope:['claims']});const result=a.review('review-1',{conflict:{id:'c-1',author:'analyst-local',revision:'wc-r1',classification:'CONFLICT',rationale:'Source disagreement'}});assert(result.ok&&result.formalReview===false&&result.reviewDecisionAuthority===false&&result.evidenceDecisionWrites===0&&result.workingConflict.author==='analyst-local'&&result.workingConflict.revision==='wc-r1');});
  test('rq.provenance-missing-original-is-derived-only',()=>{const a=new RQDomainAdapter(rqRecords());a.compare({left:ref('r1','sha-r1'),right:ref('r2','sha-r2'),workingAnalysisId:'prov-1',scope:['provenance']});const p=a.provenance('prov-1');assert(p.ok&&p.sourceAuthority==='DERIVED_ONLY'&&p.originalHashAssertion==='FORBIDDEN_DERIVED_ONLY');});
  test('rq.search-excluded-traceable-and-explicitly-includable',()=>{const a=new RQDomainAdapter(rqRecords()),normal=a.search('Excluded'),explicit=a.search('Excluded',{includeExcluded:true});assert(normal.items.length===0&&normal.excluded.length===1&&normal.trace[0].excluded===true&&explicit.items.length===1&&explicit.trace[0].included===true);});
  test('visualize.one-shared-spatial-engine-four-view-adapters',()=>{const a=new VisualizeDomainAdapter({representations:reps()}),descriptors=a.viewDescriptors(),owners=new Set(descriptors.map(x=>x.engineOwner));assert(descriptors.length===4&&owners.size===1&&descriptors.map(x=>x.mode).join()==='TREE,PATH,GRAPH,CANVAS'&&a.descriptor().universalVirtualizationOwner===false);return [...owners][0];});
  test('visualize.pointer-keyboard-selection-same-representation-identity',()=>{const a=new VisualizeDomainAdapter({representations:reps()}),tree=a.view('TREE'),pointer=tree.select({representationIds:['rep-a'],route:'pointer'}),keyboard=tree.select({representationIds:['rep-a'],route:'keyboard'});assert(pointer.ok&&keyboard.ok&&pointer.representationIds.join()===keyboard.representationIds.join()&&pointer.representationIds[0]==='rep-a');});
  test('visualize.move-representation-does-not-mutate-canonical-truth-or-relations',()=>{const state={objects:[{id:'obj-a',label:'A'},{id:'obj-b',label:'B'}],relations:[{id:'rel-1',source:'obj-a',target:'obj-b',type:'relates'}]},provider={read:()=>({ok:true,...clone(state)})},a=new VisualizeDomainAdapter({provider,representations:reps()}),before=json(state),result=a.view('CANVAS').move({representationIds:['rep-a'],dx:40,dy:20});assert(result.ok&&result.canonicalMutation===false&&result.canonicalTruthUnchanged&&result.relationsUnchanged&&before===json(state)&&a.model.edges.length===0);});
  test('visualize.link-negative-without-provider-command-zero-canonical-write',()=>{const state={objects:[{id:'obj-a'},{id:'obj-b'}],relations:[]},provider={read:()=>({ok:true,...clone(state)})},a=new VisualizeDomainAdapter({provider,representations:reps()}),before=json(state),result=a.link({sourceObjectId:'obj-a',targetObjectId:'obj-b',type:'relates'});assert(!result.ok&&result.status==='VISUALIZE_VALIDATED_RELATION_COMMAND_REQUIRED'&&result.canonicalMutation===false&&result.representationEdgeWrites===0&&before===json(state)&&a.model.edges.length===0);});
  test('visualize.link-positive-only-through-validated-provider-command',()=>{const state={objects:[{id:'obj-a'},{id:'obj-b'}],relations:[]},provider={read:()=>({ok:true,...clone(state)}),validateRelation:p=>({ok:p.sourceObjectId==='obj-a'&&p.targetObjectId==='obj-b'&&p.type==='relates',token:'validated'}),commitRelation:p=>{state.relations.push({id:'rel-1',source:p.sourceObjectId,target:p.targetObjectId,type:p.type});return {ok:true,status:'RELATION_COMMITTED',revision:'r2'}}},a=new VisualizeDomainAdapter({provider,representations:reps()}),result=a.link({sourceObjectId:'obj-a',targetObjectId:'obj-b',type:'relates'});assert(result.ok&&result.canonicalMutation===true&&state.relations.length===1&&a.model.edges.length===0);});
  test('visualize.synthetic-local-graph-never-canonical',()=>{const a=new VisualizeDomainAdapter({representations:reps()}),canonical=a.canonicalProjection(),rep=a.representationProjection('GRAPH');assert(!canonical.ok&&canonical.canonical===false&&canonical.localGraph==='SYNTHETIC_REPRESENTATION_ONLY'&&rep.canonical===false&&rep.synthetic===true&&a.descriptor().localGraphTruth==='SYNTHETIC_REPRESENTATION_ONLY');});
  test('visualize.edit-provider-updates-canonical-object-without-representation-clone',()=>{const state={objects:[{id:'obj-a',label:'A'},{id:'obj-b',label:'B'}],relations:[]},provider={read:()=>({ok:true,...clone(state)}),editObject:({objectId,patch})=>{const object=state.objects.find(x=>x.id===objectId);Object.assign(object,patch);return {ok:true,status:'OBJECT_EDITED',objectId}}},a=new VisualizeDomainAdapter({provider,representations:reps()}),result=a.edit({objectId:'obj-a',patch:{label:'Updated'}}),representations=result.representations.representations;assert(result.ok&&state.objects[0].label==='Updated'&&representations.every(x=>x.canonicalObjectCloned===false)&&!representations.some(x=>x.label==='Updated'));});
  test('visualize.viewport-keyboard-minimap-reachable-and-representation-only',()=>{const a=new VisualizeDomainAdapter({representations:reps()}),result=a.view('PATH').viewport({mode:'PATH',action:'fit',width:800,height:500});assert(result.ok&&result.canonicalMutation===false&&result.keyboardReachable&&result.minimapReachable);});
  test('visualize.surface-preserves-shared-command-owners-no-local-substitute',()=>{const r=new CommandRegistry();sharedSpatial(r);const before=Object.fromEntries([...r.commands].map(([id,c])=>[id,c.owner])),a=new VisualizeDomainAdapter({representations:reps()}),binding=bindVisualizeSurface({commands:r,adapter:a}),after=Object.fromEntries(Object.keys(before).map(id=>[id,r.commands.get(id).owner]));assert(json(before)===json(after)&&binding.missingSharedCommands.length===0&&binding.registeredCommands.every(id=>id.startsWith('visualize.'))&&new Set(binding.viewAdapters.map(x=>x.engineOwner)).size===1);});
  test('visualize.surface-missing-shared-owner-is-reported-not-forked',()=>{const r=new CommandRegistry(),a=new VisualizeDomainAdapter({representations:reps()}),binding=bindVisualizeSurface({commands:r,adapter:a});assert(binding.missingSharedCommands.includes('spatial.connect')&&!r.commands.has('spatial.connect')&&!r.commands.has('relation.undo')&&r.commands.has('visualize.select'));});
  const pass=tests.filter(t=>t.status==='PASS').length,fail=tests.length-pass;return {schema:'S09ReexecutionTests@1',pass,fail,tests};
}
